  , ("main", encStr (runMainMain r))
  , ("path", encStr (runMainPath r))
  , ("head", encBool (runMainHead r))
  , ("status", encBool (runMainStatus r))
  , ("since", encList (runMainSince r))
  , ("rc", encInt (runMainRc r))
  ]

runMainRunL :: Lens' RunMain (Int)
runMainRunL k r = (\v -> r { runMainRun = v }) <$> k (runMainRun r)
{-# INLINE runMainRunL #-}

runMainMainL :: Lens' RunMain (String)
runMainMainL k r = (\v -> r { runMainMain = v }) <$> k (runMainMain r)
{-# INLINE runMainMainL #-}

runMainPathL :: Lens' RunMain (String)
runMainPathL k r = (\v -> r { runMainPath = v }) <$> k (runMainPath r)
{-# INLINE runMainPathL #-}

runMainHeadL :: Lens' RunMain (Bool)
runMainHeadL k r = (\v -> r { runMainHead = v }) <$> k (runMainHead r)
{-# INLINE runMainHeadL #-}

runMainStatusL :: Lens' RunMain (Bool)
runMainStatusL k r = (\v -> r { runMainStatus = v }) <$> k (runMainStatus r)
{-# INLINE runMainStatusL #-}

runMainSinceL :: Lens' RunMain ([String])
runMainSinceL k r = (\v -> r { runMainSince = v }) <$> k (runMainSince r)
{-# INLINE runMainSinceL #-}

runMainRcL :: Lens' RunMain (Int)
runMainRcL k r = (\v -> r { runMainRc = v }) <$> k (runMainRc r)
{-# INLINE runMainRcL #-}

